import { useEffect, useMemo, useState } from "react";
import { Route, Switch, Link, useLocation } from "wouter";
import { AnimatePresence, motion } from "framer-motion";
import { ArrowRight, Bell, Building2, CheckCircle2, ClipboardList, Clock3, FileText, Filter, Home as HomeIcon, ImagePlus, LayoutDashboard, LogOut, Menu, Plus, Search, ShieldCheck, SlidersHorizontal, UserRound, Users, Wrench, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Toaster } from "@/components/ui/sonner";
import { toast } from "sonner";
import { ThemeProvider } from "./contexts/ThemeContext";
