import { failedUploadNames } from "../../shared/mediaUpload";
import "./index.css";

type Role = "PROPERTY_MANAGER" | "TENANT" | "TECHNICIAN" | "FLAT_OWNER";
type Status = "OPEN" | "ASSIGNED" | "IN_PROGRESS" | "RESOLVED" | "CLOSED";
type Ticket = { id: string; title: string; unit: string; category: string; priority: "LOW" | "MEDIUM" | "HIGH" | "EMERGENCY"; status: Status; age: string; assignee?: string; description: string };


const roleMeta: Record<Role, { label: string; icon: typeof Building2; accent: string; path: string }> = {
  PROPERTY_MANAGER: { label: "Property Manager", icon: Building2, accent: "violet", path: "/manager" },
  TENANT: { label: "Tenant", icon: HomeIcon, accent: "cyan", path: "/tenant" },
  TECHNICIAN: { label: "Field Technician", icon: Wrench, accent: "amber", path: "/technician" },
  FLAT_OWNER: { label: "Flat Owner", icon: ShieldCheck, accent: "emerald", path: "/owner" },
};

function maintenanceLabel(value: string, t: (english: string, arabic: string) => string) { const labels: Record<string, string> = { OPEN: t("OPEN", "مفتوح"), ASSIGNED: t("ASSIGNED", "تم التعيين"), IN_PROGRESS: t("IN PROGRESS", "قيد التنفيذ"), RESOLVED: t("RESOLVED", "تم الحل"), CLOSED: t("CLOSED", "مغلق"), LOW: t("LOW", "منخفض"), MEDIUM: t("MEDIUM", "متوسط"), HIGH: t("HIGH", "مرتفع"), EMERGENCY: t("EMERGENCY", "طارئ"), PLUMBING: t("PLUMBING", "سباكة"), ELECTRICAL: t("ELECTRICAL", "كهرباء"), HVAC: t("HVAC", "تكييف"), APPLIANCE: t("APPLIANCE", "أجهزة"), OTHER: t("OTHER", "أخرى") }; return labels[value] ?? value.replace("_", " "); }

function StatusBadge({ status }: { status: Status }) { const { t } = useLanguage(); const tones: Record<Status, string> = { OPEN: "border-rose-400/30 bg-rose-400/10 text-rose-300", ASSIGNED: "border-violet-400/30 bg-violet-400/10 text-violet-300", IN_PROGRESS: "border-amber-400/30 bg-amber-400/10 text-amber-300", RESOLVED: "border-emerald-400/30 bg-emerald-400/10 text-emerald-300", CLOSED: "border-slate-400/30 bg-slate-400/10 text-slate-300" }; const labels: Record<Status, string> = { OPEN: t("OPEN", "مفتوح"), ASSIGNED: t("ASSIGNED", "تم التعيين"), IN_PROGRESS: t("IN PROGRESS", "قيد التنفيذ"), RESOLVED: t("RESOLVED", "تم الحل"), CLOSED: t("CLOSED", "مغلق") }; return <Badge variant="outline" className={tones[status]}>{labels[status]}</Badge>; }
function PriorityBadge({ priority }: { priority: Ticket["priority"] }) { const { t } = useLanguage(); const tones = { LOW: "text-slate-300", MEDIUM: "text-cyan-300", HIGH: "text-amber-300", EMERGENCY: "text-rose-300" }; const labels = { LOW: t("LOW", "منخفض"), MEDIUM: t("MEDIUM", "متوسط"), HIGH: t("HIGH", "مرتفع"), EMERGENCY: t("EMERGENCY", "طارئ") }; return <span className={`text-[11px] font-bold tracking-[.16em] ${tones[priority]}`}>{labels[priority]}</span>; }

function RoleGate({ role, children }: { role: Role; children: React.ReactNode }) { const { user, loading } = useAuth(); const { t } = useLanguage(); if (loading) return <div className="grid min-h-screen place-items-center bg-[#080b12] text-slate-400">{t("Loading your portal...", "جاري تحميل بوابتك...")}</div>; if (!user) return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521]"><CardHeader><CardTitle>{t("Sign in to continue", "سجل الدخول للمتابعة")}</CardTitle><p className="text-slate-400">{t("Your role and workspace access are checked securely after sign-in.", "يتم التحقق من دورك وصلاحية دخولك بأمان بعد تسجيل الدخول.")}</p></CardHeader><CardContent><Button className="w-full bg-violet-500 hover:bg-violet-400" onClick={() => startLogin()}>{t("Continue to sign in", "متابعة تسجيل الدخول")} <ArrowRight size={16}/></Button></CardContent></Card></div>; if (!canAccessPortal(user.role, role)) return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md border-rose-400/20 bg-[#101521]"><CardHeader><CardTitle>{t("Access not available", "الدخول غير متاح")}</CardTitle><p className="text-slate-400">{t("This portal is reserved for another role.", "هذه البوابة مخصصة لدور آخر.")}</p></CardHeader></Card></div>; return <>{children}</>; }

function LanguageToggle() { const { language, toggleLanguage } = useLanguage(); return <button onClick={toggleLanguage} className="rounded-lg border border-white/[.1] bg-white/[.03] px-3 py-2 text-xs font-medium text-slate-300 transition hover:border-violet-400/50 hover:text-white" aria-label={language === "en" ? "Switch to Arabic" : "التبديل إلى الإنجليزية"}>{language === "en" ? "العربية" : "English"}</button>; }

function AppShell({ role, children }: { role: Role; children: React.ReactNode }) { const [, navigate] = useLocation(); const { t } = useLanguage(); const [open, setOpen] = useState(false); const meta = roleMeta[role]; const Icon = meta.icon; const roleArabic: Record<Role, string> = { PROPERTY_MANAGER: "مدير العقار", TENANT: "المستأجر", TECHNICIAN: "الفني", FLAT_OWNER: "مالك الشقة" }; const navItems = role === "PROPERTY_MANAGER" ? [{ label: t("Overview", "نظرة عامة"), href: meta.path, icon: LayoutDashboard }, { label: t("Tickets", "البلاغات"), href: `${meta.path}?view=tickets`, icon: ClipboardList }, { label: t("People", "الأشخاص"), href: `${meta.path}?view=people`, icon: Users }] as const : role === "TENANT" ? [{ label: t("Overview", "نظرة عامة"), href: meta.path, icon: LayoutDashboard }, { label: t("My requests", "طلباتي"), href: `${meta.path}?view=tickets`, icon: ClipboardList }] as const : role === "TECHNICIAN" ? [{ label: t("Today", "اليوم"), href: meta.path, icon: LayoutDashboard }, { label: t("Assigned jobs", "المهام المسندة"), href: `${meta.path}?view=tickets`, icon: ClipboardList }] as const : [{ label: t("Overview", "نظرة عامة"), href: meta.path, icon: LayoutDashboard }, { label: t("Reports", "التقارير"), href: `${meta.path}?view=reports`, icon: FileText }] as const; return <div className="min-h-screen bg-[#080b12] text-slate-100"><aside className={`fixed inset-y-0 left-0 z-40 w-72 border-r border-white/[.07] bg-[#0b0f18] p-5 transition-transform lg:translate-x-0 ${open ? "translate-x-0" : "-translate-x-full"}`}><div className="flex items-center justify-between"><Link href="/" className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-2xl bg-violet-500 text-white shadow-lg shadow-violet-500/20"><Wrench size={20}/></div><div><div className="font-semibold tracking-tight">MAINTAIN<span className="text-violet-400">R</span></div><div className="text-[10px] uppercase tracking-[.28em] text-slate-500">Operations OS</div></div></Link><button className="text-slate-500 lg:hidden" onClick={() => setOpen(false)}><X size={18}/></button></div><div className="mt-10 rounded-2xl border border-white/[.08] bg-white/[.03] p-3"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-xl bg-white/[.08] text-violet-300"><Icon size={17}/></div><div className="min-w-0"><div className="truncate text-sm font-semibold">{t(meta.label, roleArabic[role])}</div><div className="text-xs text-slate-500">{t("Westbridge Living", "ويستبريدج ليفينغ")}</div></div></div></div><nav className="mt-7 space-y-1">{navItems.map(({ label, href, icon: NavIcon }) => <Link key={label} href={href} onClick={() => setOpen(false)} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm text-slate-400 transition hover:bg-white/[.05] hover:text-white"><NavIcon size={17}/>{label}</Link>)}</nav><div className="mt-8 border-t border-white/[.06] pt-5"><div className="px-3 text-[10px] uppercase tracking-[.25em] text-slate-600">{t("Workspace", "مساحة العمل")}</div><button onClick={() => toast.info("Notification preferences are ready to connect to Resend/Twilio.")} className="mt-3 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-slate-400 hover:bg-white/[.05] hover:text-white"><Bell size={17}/>{t("Notifications", "الإشعارات")}</button><button onClick={() => navigate("/")} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-slate-400 hover:bg-white/[.05] hover:text-white"><LogOut size={17}/>{t("Sign out", "تسجيل الخروج")}</button></div></aside><main className="lg:pl-72"><header className="sticky top-0 z-30 flex h-20 items-center justify-between border-b border-white/[.07] bg-[#080b12]/85 px-5 backdrop-blur-xl lg:px-10"><button className="text-slate-400 lg:hidden" onClick={() => setOpen(true)}><Menu/></button><div className="hidden lg:block"><div className="text-sm text-slate-500">Westbridge Living / <span className="text-slate-300">{meta.label}</span></div></div><div className="flex items-center gap-4"><LanguageToggle/><div className="hidden items-center gap-2 rounded-full border border-white/[.08] bg-white/[.03] px-3 py-2 text-xs text-slate-400 sm:flex"><span className="size-2 rounded-full bg-emerald-400"/>{t("All systems operational", "جميع الأنظمة تعمل") }</div><button className="relative text-slate-400 hover:text-white" onClick={() => toast("You are all caught up.")}><Bell size={18}/><span className="absolute -right-1 -top-1 size-2 rounded-full bg-violet-400"/></button><div className="grid size-9 place-items-center rounded-full bg-gradient-to-br from-violet-400 to-cyan-400 text-xs font-bold text-[#090b12]">AR</div></div></header><div className="p-5 lg:p-10">{children}</div></main></div>; }

function Home() { const [, navigate] = useLocation(); const { t } = useLanguage(); return <div className="min-h-screen overflow-hidden bg-[#080b12] text-white"><div className="absolute left-1/2 top-[-20rem] h-[45rem] w-[65rem] -translate-x-1/2 rounded-full bg-violet-600/15 blur-3xl"/><header className="relative mx-auto flex max-w-7xl items-center justify-between px-6 py-7"><Link href="/" className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-2xl bg-violet-500"><Wrench size={20}/></div><span className="font-semibold tracking-tight">MAINTAINR</span></Link><div className="flex items-center gap-1 sm:gap-3"><Button variant="ghost" className="hidden text-slate-400 sm:inline-flex" onClick={() => navigate("/join-unit")}>{t("Join your unit", "انضم إلى وحدتك")}</Button><Button className="rounded-xl bg-white text-black hover:bg-slate-200" onClick={() => navigate("/manager")}>{t("Open workspace", "فتح مساحة العمل")} <ArrowRight size={16}/></Button></div></header><main className="relative mx-auto grid max-w-7xl gap-16 px-6 pb-20 pt-20 lg:grid-cols-[1.1fr_.9fr] lg:items-center"><section><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-violet-400/20 bg-violet-400/10 px-3 py-1.5 text-xs text-violet-200"><span className="size-1.5 rounded-full bg-violet-300"/> {t("PROPERTY OPERATIONS, REIMAGINED", "إدارة العقارات بشكل أفضل")}</div><h1 className="max-w-3xl text-5xl font-semibold leading-[1.02] tracking-[-.05em] sm:text-7xl">{t("Every repair.", "كل إصلاح.")}<br/><span className="text-violet-400">{t("One clear signal.", "إشارة واضحة واحدة.")}</span></h1><p className="mt-7 max-w-xl text-lg leading-8 text-slate-400">{t("A calm, accountable maintenance workspace for property teams, residents, technicians, and owners. From first report to final proof.", "مساحة عمل واضحة وموثوقة لمديري العقارات والسكان والفنيين والملاك، من البلاغ الأول حتى إثبات الإنجاز.")}</p><div className="mt-9 flex flex-wrap gap-3"><Button className="h-12 rounded-xl bg-violet-500 px-6 hover:bg-violet-400" onClick={() => navigate("/manager")}>{t("Explore manager portal", "استكشف بوابة المدير")} <ArrowRight size={17}/></Button><Button variant="outline" className="h-12 rounded-xl border-white/10 bg-transparent px-6 text-slate-200 hover:bg-white/5" onClick={() => navigate("/tenant")}>{t("View tenant experience", "عرض تجربة المستأجر")}</Button></div><div className="mt-12 flex items-center gap-8 text-sm text-slate-500"><span><b className="text-white">4</b> role-based portals</span><span><b className="text-white">100%</b> ticket traceability</span><span><b className="text-white">24/7</b> visibility</span></div></section><div className="relative"><div className="absolute -inset-5 rounded-[2rem] bg-violet-500/10 blur-2xl"/><Card className="relative overflow-hidden rounded-[2rem] border-white/[.1] bg-[#101521]/90 shadow-2xl shadow-black/40"><CardHeader className="border-b border-white/[.07] pb-5"><div className="flex items-center justify-between"><div><div className="text-xs uppercase tracking-[.2em] text-slate-500">Live operations</div><CardTitle className="mt-2 text-xl">Maintenance pulse</CardTitle></div><div className="rounded-xl bg-emerald-400/10 px-3 py-2 text-xs text-emerald-300">98.4% SLA</div></div></CardHeader><CardContent className="space-y-4 p-5">{[t("Role-based access", "صلاحيات حسب الدور"), t("Audit-ready ticket history", "سجل بلاغات قابل للتدقيق"), t("Proof-backed completion", "إتمام موثق بالإثبات")].map((highlight, index) => <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index*.08 }} key={highlight} className="rounded-2xl border border-white/[.07] bg-white/[.025] p-4"><div className="flex items-center gap-3"><div className="grid size-9 place-items-center rounded-xl bg-violet-400/10 text-violet-300"><CheckCircle2 size={17}/></div><div><div className="text-sm font-medium">{highlight}</div><div className="mt-1 text-xs text-slate-500">{t("Designed for clear ownership and accountability.", "مصمم لوضوح المسؤولية والمساءلة.")}</div></div></div></motion.div>)}</CardContent></Card></div></main></div>; }

function AuthPage({ mode }: { mode: "sign-in" | "sign-up" }) { const { t } = useLanguage(); return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521] p-3"><CardHeader><Link href="/" className="mb-8 text-sm text-slate-500 hover:text-white">← Back to Maintainr</Link><div className="grid size-12 place-items-center rounded-2xl bg-violet-400/10 text-violet-300"><ShieldCheck/></div><CardTitle className="mt-5 text-3xl">{mode === "sign-in" ? t("Welcome back", "مرحباً بعودتك") : t("Create your workspace account", "أنشئ حساب مساحة العمل")}</CardTitle><p className="text-slate-400">{mode === "sign-in" ? t("Sign in to access your maintenance portal.", "سجل الدخول للوصول إلى بوابة الصيانة الخاصة بك.") : t("Create an account, then join your unit or accept a manager invitation.", "أنشئ حساباً ثم انضم إلى وحدتك أو اقبل دعوة مدير العقار.")}</p></CardHeader><CardContent className="space-y-4"><Button className="h-12 w-full rounded-xl bg-violet-500 hover:bg-violet-400" onClick={() => startLogin(oauthTypeForMode(mode))}>{mode === "sign-in" ? t("Continue to sign in", "متابعة تسجيل الدخول") : t("Continue to sign up", "متابعة إنشاء الحساب")}<ArrowRight size={16}/></Button><div className="rounded-xl border border-white/[.07] bg-white/[.02] p-4 text-xs leading-5 text-slate-500">{t("Authentication is handled through the project’s secure OAuth session. Role assignment and tenant-unit binding are enforced after authentication.", "تتم المصادقة عبر جلسة آمنة. يتم تحديد الدور وربط الوحدة بعد تسجيل الدخول.")}</div><Link href={mode === "sign-in" ? "/sign-up" : "/sign-in"} className="block text-center text-sm text-violet-300 hover:text-violet-200">{mode === "sign-in" ? t("Need an account? Sign up", "ليس لديك حساب؟ أنشئ حساباً") : t("Already have an account? Sign in", "لديك حساب؟ سجل الدخول")}</Link></CardContent></Card></div>; }

function JoinUnit() { const { t } = useLanguage(); const [code, setCode] = useState(""); const [, navigate] = useLocation(); const joinUnit = trpc.onboarding.joinUnit.useMutation(); const valid = /^\d{6}$/.test(code); return <div className="grid min-h-screen place-items-center bg-[#080b12] p-6 text-white"><Card className="w-full max-w-md rounded-3xl border-white/[.1] bg-[#101521] p-3"><CardHeader><Link href="/" className="mb-8 text-sm text-slate-500 hover:text-white">← Back to Maintainr</Link><div className="grid size-12 place-items-center rounded-2xl bg-cyan-400/10 text-cyan-300"><HomeIcon/></div><CardTitle className="mt-5 text-3xl">{t("Join your unit", "انضم إلى وحدتك")}</CardTitle><p className="text-slate-400">{t("Enter the six-digit access code from your property manager.", "أدخل رمز الدخول المكون من ستة أرقام الذي أرسله مدير العقار.")}</p></CardHeader><CardContent className="space-y-5"><Input inputMode="numeric" maxLength={6} value={code} onChange={e => setCode(e.target.value.replace(/\D/g, ""))} placeholder="000000" className="h-14 border-white/10 bg-white/[.04] text-center text-2xl tracking-[.5em]"/><Button disabled={!valid} className="h-12 w-full rounded-xl bg-cyan-400 text-black hover:bg-cyan-300" onClick={async () => { try { await joinUnit.mutateAsync({ accessCode: code }); toast.success(t("Unit code verified", "تم التحقق من رمز الوحدة")); navigate("/tenant"); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to join this unit", "تعذر الانضمام إلى هذه الوحدة")); } }}>{joinUnit.isPending ? t("Joining...", "جارٍ الانضمام...") : t("Continue", "متابعة")} <ArrowRight size={16}/></Button><p className="text-center text-xs text-slate-500">{t("Code must be exactly 6 digits. Your manager can generate one from People.", "يجب أن يتكون الرمز من ستة أرقام بالضبط. يمكن لمدير العقار إنشاء الرمز من قسم الأشخاص.")}</p></CardContent></Card></div>; }

function Header({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { const { t } = useLanguage(); const arabic: Record<string, string> = { "Manager command center": "لوحة تحكم المدير", "Good morning, Alex.": "صباح الخير، أليكس.", "Here’s what needs your attention across Westbridge Living today.": "إليك أهم المهام التي تحتاج إلى انتباهك اليوم في ويستبريدج ليفينغ.", "Resident portal": "بوابة المستأجر", "Your home, looked after.": "منزلك محل اهتمامنا.", "Stay close to every request and know exactly what happens next.": "تابع كل طلب واعرف ما سيحدث بعد ذلك.", "Field operations": "العمليات الميدانية", "Your route for today.": "مسارك لهذا اليوم.", "Three jobs are queued. Start with the emergency electrical call.": "لديك ثلاث مهام. ابدأ بالبلاغ الكهربائي الطارئ.", "Owner view": "واجهة المالك", "Confidence in every detail.": "ثقة في كل التفاصيل.", "A read-only view of maintenance performance across your portfolio.": "عرض شامل لأداء الصيانة في محفظتك.", "Flat Owner": "مالك الشقة", "Property Manager": "مدير العقار", "Tenant": "المستأجر", "Field Technician": "الفني الميداني" }; return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="text-xs font-semibold uppercase tracking-[.25em] text-violet-400">{t(eyebrow, arabic[eyebrow] || eyebrow)}</div><h1 className="mt-2 text-3xl font-semibold tracking-[-.03em] text-white sm:text-4xl">{t(title, arabic[title] || title)}</h1><p className="mt-2 max-w-2xl text-sm text-slate-500">{t(description, arabic[description] || description)}</p></div>{action}</div>; }

function PeopleView() { const { t } = useLanguage(); const [tenantName, setTenantName] = useState(""); const [tenantEmail, setTenantEmail] = useState(""); const [unitId, setUnitId] = useState("1"); const [technicianName, setTechnicianName] = useState(""); const [technicianEmail, setTechnicianEmail] = useState(""); const [code, setCode] = useState<string | undefined>(); const createTenant = trpc.manager.createTenant.useMutation(); const inviteTechnician = trpc.manager.inviteTechnician.useMutation(); const generateUnitCode = trpc.manager.generateUnitCode.useMutation(); return <AppShell role="PROPERTY_MANAGER"><Header eyebrow="People" title={t("People and access", "الأشخاص والوصول")} description={t("Create tenant access, invite technicians, and generate unit codes from one simple workspace.", "أنشئ وصول المستأجرين وادعُ الفنيين وأنشئ رموز الوحدات من مساحة واحدة بسيطة.")} /><div className="grid gap-6 lg:grid-cols-3"><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Create tenant", "إنشاء مستأجر")}</CardTitle><p className="text-xs text-slate-500">{t("Create an account and connect it to a unit.", "أنشئ حساباً واربطه بوحدة.")}</p></CardHeader><CardContent className="space-y-3"><Input value={tenantName} onChange={e => setTenantName(e.target.value)} placeholder={t("Tenant name", "اسم المستأجر")} /><Input value={tenantEmail} onChange={e => setTenantEmail(e.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} type="email" /><Input value={unitId} onChange={e => setUnitId(e.target.value)} placeholder={t("Unit ID", "رقم الوحدة")} inputMode="numeric" /><Button className="w-full bg-cyan-400 text-black" onClick={async () => { try { await createTenant.mutateAsync({ name: tenantName, email: tenantEmail, unitId: Number(unitId) }); toast.success(t("Tenant created", "تم إنشاء المستأجر")); setTenantName(""); setTenantEmail(""); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to create tenant", "تعذر إنشاء المستأجر")); } }}>{t("Create tenant", "إنشاء المستأجر")}</Button></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Invite technician", "دعوة فني")}</CardTitle><p className="text-xs text-slate-500">{t("Send a secure invitation for field operations.", "أرسل دعوة آمنة للعمليات الميدانية.")}</p></CardHeader><CardContent className="space-y-3"><Input value={technicianName} onChange={e => setTechnicianName(e.target.value)} placeholder={t("Technician name", "اسم الفني")} /><Input value={technicianEmail} onChange={e => setTechnicianEmail(e.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} type="email" /><Button className="w-full bg-violet-500" onClick={async () => { try { await inviteTechnician.mutateAsync({ name: technicianName, email: technicianEmail }); toast.success(t("Invitation sent", "تم إرسال الدعوة")); setTechnicianName(""); setTechnicianEmail(""); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to send invitation", "تعذر إرسال الدعوة")); } }}>{t("Send invitation", "إرسال الدعوة")}</Button></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle>{t("Unit access code", "رمز دخول الوحدة")}</CardTitle><p className="text-xs text-slate-500">{t("Generate a six-digit code for a tenant.", "أنشئ رمزاً من ستة أرقام للمستأجر.")}</p></CardHeader><CardContent className="space-y-3"><Input value={unitId} onChange={e => setUnitId(e.target.value)} placeholder={t("Unit ID", "رقم الوحدة")} inputMode="numeric" /><Button className="w-full bg-emerald-500 text-black" onClick={async () => { try { const result = await generateUnitCode.mutateAsync({ unitId: Number(unitId) }); setCode(result.accessCode); toast.success(t("Code generated", "تم إنشاء الرمز")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to generate code", "تعذر إنشاء الرمز")); } }}>{t("Generate code", "إنشاء الرمز")}</Button>{code && <div className="rounded-xl border border-emerald-400/30 bg-emerald-400/10 p-4 text-center text-2xl font-semibold tracking-[.35em] text-emerald-200">{code}</div>}</CardContent></Card></div></AppShell>; }

function ManagerTicketActions({ ticketId, priority, technicians, isLoading, isError }: { ticketId: string; priority: "LOW" | "MEDIUM" | "HIGH" | "EMERGENCY"; technicians: Array<{ id: number; name: string | null; email: string | null }>; isLoading: boolean; isError: boolean }) { const { t } = useLanguage(); const [selectedTechnicianId, setSelectedTechnicianId] = useState("none"); const assignTicket = trpc.tickets.assign.useMutation(); const setPriority = trpc.tickets.setPriority.useMutation(); const numericId = ticketId.startsWith("MT-") ? Number(ticketId.replace("MT-", "")) : 0; return <div className="mt-3 flex flex-wrap items-center gap-2" onClick={event => event.stopPropagation()}>{isLoading ? <span className="text-[11px] text-slate-500">{t("Loading technicians...", "جارٍ تحميل الفنيين...")}</span> : isError ? <span className="text-[11px] text-rose-300">{t("Technicians unavailable", "الفنيون غير متاحين")}</span> : technicians.length === 0 ? <span className="text-[11px] text-slate-500">{t("No technicians yet", "لا يوجد فنيون بعد")}</span> : <><Select value={selectedTechnicianId} onValueChange={setSelectedTechnicianId}><SelectTrigger className="h-8 w-36 border-white/10 bg-transparent text-[11px]"><SelectValue placeholder={t("Choose technician", "اختر الفني")} /></SelectTrigger><SelectContent><SelectItem value="none">{t("Choose technician", "اختر الفني")}</SelectItem>{technicians.map(technician => <SelectItem key={technician.id} value={String(technician.id)}>{technician.name ?? technician.email ?? `#${technician.id}`}</SelectItem>)}</SelectContent></Select><Button size="sm" variant="outline" disabled={selectedTechnicianId === "none" || assignTicket.isPending || !numericId} className="border-white/10 bg-transparent text-xs" onClick={async () => { if (selectedTechnicianId === "none" || !numericId) return; try { await assignTicket.mutateAsync({ ticketId: numericId, technicianId: Number(selectedTechnicianId) }); toast.success(t("Technician assigned", "تم تعيين الفني")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to assign technician", "تعذر تعيين الفني")); } }}>{assignTicket.isPending ? t("Assigning...", "جارٍ التعيين...") : t("Assign", "تعيين")}</Button></>}<Button size="sm" variant="outline" disabled={setPriority.isPending || !numericId} className="border-white/10 bg-transparent text-xs" onClick={async () => { const choices = ["LOW", "MEDIUM", "HIGH", "EMERGENCY"] as const; const next = choices[(choices.indexOf(priority) + 1) % choices.length]; try { await setPriority.mutateAsync({ ticketId: numericId, priority: next }); toast.success(t(`Priority: ${next}`, `الأولوية: ${next}`)); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to update priority", "تعذر تحديث الأولوية")); } }}>{setPriority.isPending ? t("Saving...", "جارٍ الحفظ...") : t("Priority", "الأولوية")}</Button></div>; }

function ManagerPortal() { const { t } = useLanguage(); const updateStatus = trpc.tickets.updateStatus.useMutation(); const assignTicket = trpc.tickets.assign.useMutation(); const setPriority = trpc.tickets.setPriority.useMutation(); const technicians = trpc.manager.listTechnicians.useQuery(undefined, { retry: false }); const [selectedTechnicianId, setSelectedTechnicianId] = useState(""); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const [tickets, setTickets] = useState<Ticket[]>([]); useEffect(() => { if (liveTickets.data) setTickets(liveTickets.data.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description }))); }, [liveTickets.data]); const [view, setView] = useState<"kanban" | "list">("kanban"); const [filter, setFilter] = useState("ALL"); const [priorityFilter, setPriorityFilter] = useState("ALL"); const [categoryFilter, setCategoryFilter] = useState("ALL"); const filtered = tickets.filter(t => (filter === "ALL" || t.status === filter) && (priorityFilter === "ALL" || t.priority === priorityFilter) && (categoryFilter === "ALL" || t.category === categoryFilter)); const statuses: Status[] = ["OPEN", "ASSIGNED", "IN_PROGRESS", "RESOLVED"]; if (typeof window !== "undefined" && new URLSearchParams(window.location.search).get("view") === "people") return <PeopleView />; return <AppShell role="PROPERTY_MANAGER"><Header eyebrow="Manager command center" title="Good morning, Alex." description="Here’s what needs your attention across Westbridge Living today." action={<div className="flex gap-2"><Button variant="outline" className="border-white/10 bg-transparent" onClick={() => setView(view === "kanban" ? "list" : "kanban")}><LayoutDashboard size={16}/>{view === "kanban" ? t("List view", "عرض القائمة") : t("Kanban view", "عرض كانبان")}</Button><Button className="bg-violet-500 hover:bg-violet-400" onClick={() => toast.success("New ticket composer opened") }><Plus size={16}/>{t("New ticket", "بلاغ جديد")}</Button></div>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{([{ label: "Open tickets", value: "12", sub: "+3 this week", icon: ClipboardList, color: "text-rose-300" }, { label: "In progress", value: "07", sub: "2 due today", icon: Clock3, color: "text-amber-300" }, { label: "Resolved this month", value: "34", sub: "+18.2%", icon: CheckCircle2, color: "text-emerald-300" }, { label: "Active technicians", value: "08", sub: "All available", icon: Users, color: "text-cyan-300" }] as const).map(stat => { const StatIcon = stat.icon; return <Card key={stat.label} className="border-white/[.07] bg-[#101521]"><CardContent className="flex items-center justify-between p-5"><div><div className="text-xs text-slate-500">{stat.label}</div><div className="mt-2 text-3xl font-semibold">{stat.value}</div><div className="mt-1 text-xs text-slate-500">{stat.sub}</div></div><StatIcon className={stat.color} size={22}/></CardContent></Card>; })}</div><Card className="mt-8 border-white/[.07] bg-[#101521]"><CardHeader className="flex flex-row items-center justify-between border-b border-white/[.07] pb-4"><div><CardTitle className="text-lg">{t("Ticket operations", "عمليات البلاغات")}</CardTitle><p className="mt-1 text-xs text-slate-500">{t("Track every maintenance request from report to resolution.", "تابع كل طلب صيانة من البلاغ حتى الحل.")}</p></div><div className="flex gap-2"><Select value={filter} onValueChange={setFilter}><SelectTrigger className="w-36 border-white/10 bg-white/[.03] text-xs"><Filter size={14}/><SelectValue placeholder="Filter status"/></SelectTrigger><SelectContent><SelectItem value="ALL">{t("All statuses", "كل الحالات")}</SelectItem>{statuses.map(s => <SelectItem key={s} value={s}>{maintenanceLabel(s, t)}</SelectItem>)}</SelectContent></Select><Select value={priorityFilter} onValueChange={setPriorityFilter}><SelectTrigger className="w-32 border-white/10 bg-white/[.03] text-xs"><SelectValue placeholder="Priority"/></SelectTrigger><SelectContent><SelectItem value="ALL">{t("All priorities", "كل الأولويات")}</SelectItem>{["LOW","MEDIUM","HIGH","EMERGENCY"].map(s => <SelectItem key={s} value={s}>{maintenanceLabel(s, t)}</SelectItem>)}</SelectContent></Select><Select value={categoryFilter} onValueChange={setCategoryFilter}><SelectTrigger className="w-32 border-white/10 bg-white/[.03] text-xs"><SelectValue placeholder="Category"/></SelectTrigger><SelectContent><SelectItem value="ALL">{t("All categories", "كل الفئات")}</SelectItem>{["PLUMBING","ELECTRICAL","HVAC","APPLIANCE","OTHER"].map(s => <SelectItem key={s} value={s}>{maintenanceLabel(s, t)}</SelectItem>)}</SelectContent></Select><Button size="icon" variant="outline" className="border-white/10 bg-transparent"><SlidersHorizontal size={16}/></Button></div></CardHeader><CardContent className="p-5">{view === "kanban" ? <div className="grid gap-4 xl:grid-cols-4">{statuses.map(status => <div key={status} className="min-w-0"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2 text-xs font-semibold text-slate-300"><span className={`size-2 rounded-full ${status === "OPEN" ? "bg-rose-400" : status === "ASSIGNED" ? "bg-violet-400" : status === "IN_PROGRESS" ? "bg-amber-400" : "bg-emerald-400"}`}/>{maintenanceLabel(status, t)}</div><span className="text-xs text-slate-600">{filtered.filter(t => t.status === status).length}</span></div><div className="space-y-3">{filtered.filter(t => t.status === status).map(t => <motion.div layout key={t.id} className="cursor-pointer rounded-2xl border border-white/[.07] bg-white/[.025] p-4 transition hover:border-violet-400/40" onClick={async () => { if (t.status !== "RESOLVED") { const nextStatus = status === "OPEN" ? "ASSIGNED" : status === "ASSIGNED" ? "IN_PROGRESS" : "RESOLVED"; setTickets(tickets.map(item => item.id === t.id ? {...item, status: nextStatus} : item)); try { if (t.id.startsWith("MT-")) await updateStatus.mutateAsync({ ticketId: Number(t.id.replace("MT-", "")), status: nextStatus }); toast.success("Ticket updated and audit log recorded"); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to update ticket"); } } }}><div className="flex items-start justify-between gap-2"><span className="text-[11px] text-slate-500">{t.id}</span><PriorityBadge priority={t.priority}/></div><div className="mt-2 text-sm font-medium leading-5">{t.title}</div><div className="mt-3 flex items-center justify-between text-xs text-slate-500"><span>{t.unit} · {t.category}</span><span>{t.age}</span></div>{t.assignee && <div className="mt-3 flex items-center gap-2 border-t border-white/[.06] pt-3 text-xs text-slate-400"><div className="grid size-5 place-items-center rounded-full bg-violet-400/20 text-[9px] text-violet-200">{t.assignee.split(" ").map(n => n[0]).join("")}</div>{t.assignee}</div>}<ManagerTicketActions ticketId={t.id} priority={t.priority} technicians={technicians.data ?? []} isLoading={technicians.isLoading} isError={technicians.isError}/></motion.div>)}</div></div>)}</div> : <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="text-xs uppercase tracking-wider text-slate-600"><tr><th className="pb-4">Ticket</th><th className="pb-4">Unit</th><th className="pb-4">Priority</th><th className="pb-4">Status</th><th className="pb-4">Assignee</th><th className="pb-4">Actions</th></tr></thead><tbody>{filtered.map(t => <tr key={t.id} className="border-t border-white/[.06]"><td className="py-4 font-medium">{t.title}<div className="text-xs text-slate-600">{t.id}</div></td><td className="py-4 text-slate-400">{t.unit}</td><td className="py-4"><PriorityBadge priority={t.priority}/></td><td className="py-4"><StatusBadge status={t.status}/></td><td className="py-4 text-slate-400">{t.assignee || "Unassigned"}</td><td className="py-4"><ManagerTicketActions ticketId={t.id} priority={t.priority} technicians={technicians.data ?? []} isLoading={technicians.isLoading} isError={technicians.isError}/></td></tr>)}</tbody></table></div>}</CardContent></Card></AppShell>; }

function TenantPortal() { const { t } = useLanguage(); const { user } = useAuth(); const createTicket = trpc.tickets.create.useMutation(); const attachMedia = trpc.tickets.attachMedia.useMutation(); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const ticketSource = liveTickets.data?.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description })) ?? []; const [submitted, setSubmitted] = useState(false); const [createdTicketId, setCreatedTicketId] = useState<number | undefined>(); const [pendingFiles, setPendingFiles] = useState<File[]>([]); const [mediaStatus, setMediaStatus] = useState<"idle" | "uploading" | "complete" | "partial">("idle"); const [mediaErrors, setMediaErrors] = useState<string[]>([]); const [historyQuery, setHistoryQuery] = useState(""); const [title, setTitle] = useState(""); const [category, setCategory] = useState<"PLUMBING" | "ELECTRICAL" | "HVAC" | "APPLIANCE" | "OTHER">("OTHER"); const [description, setDescription] = useState(""); const [preferredAccessTime, setPreferredAccessTime] = useState(""); const activeTicket = ticketSource.find(t => ["OPEN", "ASSIGNED", "IN_PROGRESS"].includes(t.status)); const history = ticketSource.filter(t => t.status === "RESOLVED" && `${t.title} ${t.id} ${t.category}`.toLowerCase().includes(historyQuery.toLowerCase())); return <AppShell role="TENANT"><Header eyebrow="Resident portal" title="Your home, looked after." description="Stay close to every request and know exactly what happens next." action={<Button className="bg-cyan-400 text-black hover:bg-cyan-300" onClick={() => document.getElementById("submit-ticket")?.scrollIntoView({ behavior: "smooth" })}><Plus size={16}/>{t("Report an issue", "إبلاغ عن مشكلة")}</Button>}/><Card className="overflow-hidden border-cyan-400/20 bg-gradient-to-br from-cyan-400/[.12] to-[#101521]"><CardContent className="p-6 sm:p-8"><div className="flex flex-col justify-between gap-8 sm:flex-row"><div><div className="text-xs uppercase tracking-[.22em] text-cyan-300">{t("Active request", "البلاغ النشط")} · {activeTicket?.id ?? "—"}</div><h2 className="mt-3 text-2xl font-semibold">{activeTicket?.title ?? t("No active request", "لا يوجد بلاغ نشط")}</h2><p className="mt-2 text-sm text-slate-400">{activeTicket ? `${activeTicket.age} · ${activeTicket.unit}` : t("Submit a request to see updates here.", "أرسل بلاغاً لرؤية التحديثات هنا.")}</p></div><StatusBadge status={activeTicket?.status ?? "OPEN"}/></div><div className="mt-10 grid grid-cols-4 gap-2">{["OPEN", "ASSIGNED", "IN_PROGRESS", "RESOLVED"].map((step, index) => <div key={step}><div className={`h-1.5 rounded-full ${index < 3 ? "bg-cyan-400" : "bg-white/10"}`}/><div className={`mt-2 text-[10px] uppercase tracking-wider ${index < 3 ? "text-cyan-200" : "text-slate-600"}`}>{maintenanceLabel(step, t)}</div></div>)}</div><div className="mt-6 flex items-center gap-3 text-sm text-slate-400"><Clock3 size={16} className="text-cyan-300"/>{t("Your technician is expected today between 2:00–4:00 PM.", "من المتوقع وصول الفني اليوم بين الساعة 2:00 و4:00 مساءً.")}</div></CardContent></Card><div className="mt-8 grid gap-8 lg:grid-cols-[1.1fr_.9fr]"><Card id="submit-ticket" className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle className="text-lg">{t("Report a maintenance issue", "إبلاغ عن مشكلة صيانة")}</CardTitle><p className="text-xs text-slate-500">{t("Give your property team enough context to resolve it quickly.", "أضف التفاصيل التي تساعد فريق العقار على حل المشكلة بسرعة.")}</p></CardHeader><CardContent className="space-y-4"><Input value={title} onChange={e => setTitle(e.target.value)} placeholder={t("Short title, e.g. Bathroom tap is leaking", "عنوان مختصر، مثال: صنبور الحمام يتسرب") } className="border-white/10 bg-white/[.03]"/><Select value={category} onValueChange={value => setCategory(value as typeof category)}><SelectTrigger className="border-white/10 bg-white/[.03]"><SelectValue placeholder={t("Select category", "اختر الفئة")}/></SelectTrigger><SelectContent>{["PLUMBING","ELECTRICAL","HVAC","APPLIANCE","OTHER"].map(x => <SelectItem key={x} value={x}>{maintenanceLabel(x, t)}</SelectItem>)}</SelectContent></Select><Textarea value={description} onChange={e => setDescription(e.target.value)} placeholder={t("Describe what is happening...", "اشرح ما يحدث...")} className="min-h-28 border-white/10 bg-white/[.03]"/><div className="grid gap-4 sm:grid-cols-2"><Input value={preferredAccessTime} onChange={e => setPreferredAccessTime(e.target.value)} placeholder={t("Preferred access time", "وقت الدخول المفضل")} className="border-white/10 bg-white/[.03]"/><label className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-white/15 bg-white/[.02] text-sm text-slate-400 hover:border-cyan-400/40"><ImagePlus size={17}/>{pendingFiles.length ? `${pendingFiles.length} ${t("file(s) selected", "ملفات محددة")}` : t("Add photo/video", "إضافة صورة أو فيديو")}<input type="file" className="hidden" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" multiple onChange={e => setPendingFiles(Array.from(e.target.files ?? []))}/></label></div><Button className="w-full bg-cyan-400 text-black hover:bg-cyan-300" onClick={async () => { if (!user?.unitId || title.trim().length < 3 || description.trim().length < 10) { toast.error(t("Add a title and at least 10 characters of detail.", "أضف عنواناً ووصفاً من 10 أحرف على الأقل.")); return; } try { const created = await createTicket.mutateAsync({ unitId: user.unitId, title, description, category, priority: "MEDIUM", preferredAccessTime }); setCreatedTicketId(created.ticketId); if (pendingFiles.length) { setMediaStatus("uploading"); const results = await Promise.allSettled(pendingFiles.map(file => new Promise<void>((resolve, reject) => { const reader = new FileReader(); reader.onload = async () => { try { await attachMedia.mutateAsync({ ticketId: created.ticketId, fileName: file.name, contentType: file.type as "image/jpeg" | "image/png" | "image/webp" | "video/mp4" | "video/quicktime", base64Data: String(reader.result) }); resolve(); } catch (error) { reject(error); } }; reader.onerror = () => reject(new Error("Unable to read media file")); reader.readAsDataURL(file); }))); const failed = failedUploadNames(pendingFiles.map(file => file.name), results); setMediaErrors(failed); setMediaStatus(failed.length ? "partial" : "complete"); if (failed.length) toast.warning(t(`${failed.length} file(s) need retry.`, `يحتاج ${failed.length} ملف إلى إعادة المحاولة.`)); } setPendingFiles([]); setSubmitted(true); setTitle(""); setDescription(""); toast.success(t("Ticket submitted. Your property team has been notified.", "تم إرسال البلاغ وإخطار فريق العقار.")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to submit ticket", "تعذر إرسال البلاغ")); } }}>{createTicket.isPending ? t("Submitting...", "جارٍ الإرسال...") : mediaStatus === "uploading" ? t("Uploading media...", "جارٍ رفع الوسائط...") : t("Submit maintenance request", "إرسال طلب الصيانة")} <ArrowRight size={16}/></Button>{submitted && mediaStatus === "partial" && <div className="rounded-xl bg-amber-400/10 p-3 text-sm text-amber-200">{t("Ticket created, but some files need retry: ", "تم إنشاء البلاغ، لكن بعض الملفات تحتاج إلى إعادة المحاولة: ")}{mediaErrors.join(", ")}</div>}{submitted && <div className="rounded-xl bg-emerald-400/10 p-3 text-sm text-emerald-300">{t("Request received. You’ll get updates here and by email.", "تم استلام الطلب. ستصلك التحديثات هنا وعبر البريد الإلكتروني.")}</div>}</CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardHeader><CardTitle className="text-lg">{t("Maintenance history", "سجل الصيانة")}</CardTitle><div className="relative mt-3"><Search className="absolute left-3 top-2.5 text-slate-600" size={15}/><Input value={historyQuery} onChange={e => setHistoryQuery(e.target.value)} placeholder={t("Search repairs...", "البحث في الإصلاحات...")} className="border-white/10 bg-white/[.03] pl-9"/></div></CardHeader><CardContent className="space-y-1">{history.map(t => <div key={t.id} className="flex items-center justify-between border-b border-white/[.06] py-4"><div><div className="text-sm">{t.title}</div><div className="mt-1 text-xs text-slate-500">{t.id} · {t.age}</div></div><CheckCircle2 size={17} className="text-emerald-300"/></div>)}</CardContent></Card></div></AppShell>; }

function TechnicianPortal() { const { t } = useLanguage(); const attachMedia = trpc.tickets.attachMedia.useMutation(); const updateStatus = trpc.tickets.updateStatus.useMutation(); const completeTicket = trpc.technician.complete.useMutation(); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const jobSource = liveTickets.data?.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description, assignee: "Assigned technician" })) ?? []; const [selectedTicketId, setSelectedTicketId] = useState(() => Number(jobSource[0]?.id.replace("MT-", "") ?? 0)); const selectedJob = jobSource.find(job => Number(job.id.replace("MT-", "")) === selectedTicketId) ?? jobSource[0]; const [status, setStatus] = useState<Status>(selectedJob?.status ?? "ASSIGNED"); useEffect(() => { if (selectedJob?.status) setStatus(selectedJob.status); }, [selectedJob?.id, selectedJob?.status]); const [notes, setNotes] = useState(""); const [proofUrl, setProofUrl] = useState(""); const canResolve = notes.trim().length > 5 && proofUrl.length > 0; return <AppShell role="TECHNICIAN"><Header eyebrow="Field operations" title="Your route for today." description={selectedJob ? `${jobSource.length} ${t("assigned jobs available", "مهام مسندة متاحة")} · ${selectedJob.category}` : t("Select an assigned job to begin.", "اختر مهمة مسندة للبدء.")} action={<div className="rounded-xl border border-amber-400/20 bg-amber-400/10 px-3 py-2 text-xs text-amber-200">{new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })} · {t("Today", "اليوم")}</div>}/><div className="grid gap-8 xl:grid-cols-[.9fr_1.1fr]"><Card className="border-white/[.07] bg-[#101521]"><CardHeader><div className="flex items-center justify-between"><CardTitle className="text-lg">{t("Assigned jobs", "المهام المسندة")}</CardTitle><Badge variant="outline" className="border-white/10 text-slate-400">3 jobs</Badge></div></CardHeader><CardContent className="space-y-3">{jobSource.filter(t => t.assignee).sort((a,b) => a.priority === "EMERGENCY" ? -1 : b.priority === "EMERGENCY" ? 1 : 0).map((t, i) => <div key={t.id} onClick={() => setSelectedTicketId(Number(t.id.replace("MT-", "")))} className={`cursor-pointer rounded-2xl border p-4 ${i === 0 ? "border-amber-400/30 bg-amber-400/[.06]" : "border-white/[.07] bg-white/[.025]"}`}><div className="flex justify-between"><span className="text-[11px] text-slate-500">{t.id} · {t.unit}</span><PriorityBadge priority={t.priority}/></div><div className="mt-2 font-medium">{t.title}</div><div className="mt-3 flex items-center justify-between"><StatusBadge status={t.status}/><span className="text-xs text-slate-500">{t.category}</span></div></div>)}</CardContent></Card><Card className="border-amber-400/20 bg-[#101521]"><CardHeader><div className="flex items-center justify-between"><div><div className="text-xs uppercase tracking-[.2em] text-amber-300">{t("Current job", "المهمة الحالية")} · MT-{selectedTicketId}</div><CardTitle className="mt-2 text-xl">{selectedJob?.title ?? t("Select a job", "اختر مهمة") }</CardTitle></div><PriorityBadge priority={selectedJob?.priority ?? "MEDIUM"}/></div><p className="text-sm text-slate-400">{selectedJob?.unit ?? t("Selected unit", "الوحدة المحددة")} · {selectedJob?.category ?? ""} · {t("Tenant access confirmed", "تم تأكيد دخول المستأجر")}</p></CardHeader><CardContent className="space-y-5"><div className="grid gap-3 rounded-2xl border border-white/[.07] bg-white/[.025] p-4 sm:grid-cols-2"><div><div className="text-xs text-slate-500">{t("Location", "الموقع")}</div><div className="mt-1 text-sm">{selectedJob?.unit ?? t("Selected unit", "الوحدة المحددة")}</div></div><div><div className="text-xs text-slate-500">{t("Access note", "ملاحظة الدخول")}</div><div className="mt-1 text-sm">{t("Access instructions available in the ticket", "تعليمات الدخول متاحة في البلاغ")}</div></div></div><div className="flex gap-2"><Button variant={status === "IN_PROGRESS" ? "default" : "outline"} className={status === "IN_PROGRESS" ? "bg-amber-400 text-black hover:bg-amber-300" : "border-white/10 bg-transparent"} onClick={async () => { try { await updateStatus.mutateAsync({ ticketId: selectedTicketId, status: "IN_PROGRESS" }); setStatus("IN_PROGRESS"); toast.success(t("Job started", "بدأت المهمة")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to update job", "تعذر تحديث المهمة")); } }}>{t("Start job", "بدء المهمة")}</Button><Button variant="outline" className="border-white/10 bg-transparent" onClick={() => toast.info("Tenant notified of your ETA")}>{t("Notify tenant", "إبلاغ المستأجر")}</Button></div><div className="border-t border-white/[.07] pt-5"><div className="mb-3 text-sm font-semibold">{t("Completion checklist", "قائمة إتمام المهمة")}</div><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-white/15 p-4 text-sm text-slate-400 hover:border-amber-400/40"><ImagePlus size={18} className="text-amber-300"/><span>{proofUrl ? t("Proof photo attached", "تم إرفاق صورة الإثبات") : t("Upload proof photo (required)", "إرفاق صورة إثبات (مطلوب)")}</span><input type="file" className="hidden" accept="image/*" onChange={e => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = async () => { try { const result = await attachMedia.mutateAsync({ ticketId: selectedTicketId, fileName: file.name, contentType: file.type as "image/jpeg" | "image/png" | "image/webp" | "video/mp4" | "video/quicktime", base64Data: String(reader.result) }); setProofUrl(result.url); toast.success(t("Proof photo uploaded", "تم رفع صورة الإثبات")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Upload failed", "فشل الرفع")); } }; reader.readAsDataURL(file); }}/>{proofUrl && <CheckCircle2 className="ml-auto text-emerald-300" size={17}/>}</label><Textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder={t("Resolution notes (required before completing)", "ملاحظات الحل (مطلوبة قبل الإتمام)")} className="mt-3 min-h-24 border-white/10 bg-white/[.03]"/><Button disabled={!canResolve} className="mt-3 w-full bg-emerald-400 text-black hover:bg-emerald-300 disabled:cursor-not-allowed disabled:opacity-40" onClick={async () => { try { await completeTicket.mutateAsync({ ticketId: selectedTicketId, proofPhotoUrl: proofUrl, resolutionNotes: notes }); setStatus("RESOLVED"); toast.success(t("Job complete. Proof and notes added to the audit log.", "اكتملت المهمة وتمت إضافة الإثبات والملاحظات إلى سجل التدقيق.")); } catch (error) { toast.error(error instanceof Error ? error.message : t("Unable to complete job", "تعذر إكمال المهمة")); } }}>{t("Mark as resolved", "تحديد كمحلول")} <CheckCircle2 size={16}/></Button>{!canResolve && <p className="mt-2 text-center text-xs text-slate-600">{t("Proof photo and resolution notes are required.", "صورة الإثبات وملاحظات الحل مطلوبة.")}</p>}</div></CardContent></Card></div></AppShell>; }

function OwnerPortal() { const { t } = useLanguage(); const liveTickets = trpc.tickets.list.useQuery(undefined, { retry: false }); const portfolioTickets = liveTickets.data?.map(ticket => ({ id: `MT-${ticket.id}`, title: ticket.title, unit: `Unit ${ticket.unitId}`, category: ticket.category, priority: ticket.priority, status: ticket.status, age: new Date(ticket.createdAt).toLocaleDateString(), description: ticket.description })) ?? []; return <AppShell role="FLAT_OWNER"><Header eyebrow="Owner view" title="Confidence in every detail." description="A read-only view of maintenance performance across your portfolio." action={<Button variant="outline" className="border-white/10 bg-transparent" onClick={() => toast.info("Owner reports are being prepared")}>{t("Export report", "تصدير التقرير")} <FileText size={16}/></Button>}/><div className="grid gap-4 sm:grid-cols-3"><Card className="border-white/[.07] bg-[#101521]"><CardContent className="p-5"><div className="text-xs text-slate-500">{t("Portfolio health", "صحة المحفظة")}</div><div className="mt-2 text-3xl font-semibold text-emerald-300">96%</div><div className="mt-1 text-xs text-slate-500">{t("Units with no open issues", "الوحدات بدون مشاكل مفتوحة")}</div></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardContent className="p-5"><div className="text-xs text-slate-500">{t("Average resolution", "متوسط مدة الحل")}</div><div className="mt-2 text-3xl font-semibold">1.8d</div><div className="mt-1 text-xs text-slate-500">{t("Down 0.4d this month", "أقل بـ 0.4 يوم هذا الشهر")}</div></CardContent></Card><Card className="border-white/[.07] bg-[#101521]"><CardContent className="p-5"><div className="text-xs text-slate-500">{t("Open exposure", "التكلفة المفتوحة")}</div><div className="mt-2 text-3xl font-semibold text-amber-300">$8.4k</div><div className="mt-1 text-xs text-slate-500">{t("Estimated maintenance spend", "تقدير نفقات الصيانة")}</div></CardContent></Card></div><Card className="mt-8 border-white/[.07] bg-[#101521]"><CardHeader><CardTitle className="text-lg">{t("Recent portfolio activity", "أحدث نشاط في المحفظة")}</CardTitle></CardHeader><CardContent className="space-y-2">{portfolioTickets.map(t => <div key={t.id} className="flex flex-col justify-between gap-3 rounded-2xl border border-white/[.06] bg-white/[.02] p-4 sm:flex-row sm:items-center"><div><div className="font-medium">{t.title}</div><div className="mt-1 text-xs text-slate-500">{t.id} · Unit {t.unit} · {t.category}</div></div><div className="flex items-center gap-4"><PriorityBadge priority={t.priority}/><StatusBadge status={t.status}/></div></div>)}</CardContent></Card></AppShell>; }

export default function App() { return <LanguageProvider><ThemeProvider defaultTheme="dark"><Toaster/><Switch><Route path="/" component={Home}/><Route path="/sign-in"><AuthPage mode="sign-in"/></Route><Route path="/sign-up"><AuthPage mode="sign-up"/></Route><Route path="/join-unit" component={JoinUnit}/><Route path="/manager"><RoleGate role="PROPERTY_MANAGER"><ManagerPortal/></RoleGate></Route><Route path="/tenant"><RoleGate role="TENANT"><TenantPortal/></RoleGate></Route><Route path="/technician"><RoleGate role="TECHNICIAN"><TechnicianPortal/></RoleGate></Route><Route path="/owner"><RoleGate role="FLAT_OWNER"><OwnerPortal/></RoleGate></Route><Route component={Home}/></Switch></ThemeProvider></LanguageProvider>; }
